package kr.tong.sky;
import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.nio.file.*;import java.util.*;import java.time.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(manifest=Config.NONE,sdk=35,packageName="kr.tong.sky",instrumentedPackages={"kr.tong.sky"})
public class ReferenceParityTest {
 JSONObject catalog()throws Exception{return new JSONObject(Files.readString(Path.of(System.getProperty("tongsky.assets"),"repeat-marker-catalog.json")));}
 @Test public void everyStoredRouteMonthMatchesWebsiteDayFlagsAndEvidence()throws Exception{
  JSONArray cases;try(var in=getClass().getResourceAsStream("/parity.json")){cases=new JSONArray(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}
  JSONObject selected=catalog();ReferenceMarkerRules.Context context=new ReferenceMarkerRules.Context();for(int i=0;i<cases.length();i++){JSONObject raw=cases.getJSONObject(i).getJSONObject("raw");context.add(raw,raw.getLong("success"));}
  int dates=0,bonus=0,upgrade=0;for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i),raw=c.getJSONObject("raw");String before=raw.toString();JSONObject view=RepeatMarkerPolicy.calendar(raw,selected,context);String key=Search.key(raw);assertEquals(key,before,raw.toString());compare(key,c.opt("policy"),view.opt("repeatMarkerPolicy"));JSONArray expected=c.getJSONArray("days"),actual=view.getJSONArray("dates");assertEquals(expected.length(),actual.length());
   for(int n=0;n<expected.length();n++){JSONObject e=expected.getJSONObject(n),a=actual.getJSONObject(n);String label=key+" "+e.getString("date");assertEquals(label,e.getBoolean("excluded"),RepeatMarkerPolicy.excluded(a));assertEquals(label,e.getBoolean("review"),RepeatMarkerPolicy.review(a));for(int f=0;f<Search.ALL_FIELDS.length;f++)assertEquals(label+" "+Search.ALL_FIELDS[f],e.getJSONArray("marks").getBoolean(f),SeatMarks.marked(a,Search.ALL_FIELDS[f],false));dates++;
    String date=e.getString("date");if((raw.getString("origin").equals("MXP")||raw.getString("destination").equals("MXP"))&&date.compareTo("2026-11-03")>=0&&date.compareTo("2027-10-28")<=0){if(SeatMarks.marked(a,"prestigeAward",false))bonus++;if(SeatMarks.marked(a,"prestigeUpgrade",false))upgrade++;}
   }
  }assertEquals(12,bonus);assertEquals(43,upgrade);System.out.println("PARITY_PASS: "+cases.length()+" route-months / "+dates+" dates; Milan P12 U43; original inputs preserved");
 }
 Set<String> keys(JSONObject o){Set<String> result=new TreeSet<>();o.keys().forEachRemaining(result::add);return result;}
 void compare(String at,Object expected,Object actual)throws Exception{if(expected instanceof JSONObject e){assertTrue(at,actual instanceof JSONObject);JSONObject a=(JSONObject)actual;assertEquals(at,keys(e),keys(a));for(String key:keys(e))compare(at+"."+key,e.get(key),a.get(key));}else if(expected instanceof JSONArray e){assertTrue(at,actual instanceof JSONArray);JSONArray a=(JSONArray)actual;assertEquals(at,e.length(),a.length());for(int i=0;i<e.length();i++)compare(at+"["+i+"]",e.get(i),a.get(i));}else assertEquals(at,String.valueOf(expected),String.valueOf(actual));}
 @Test public void everyEligibleCatalogRouteBothDirectionsUsesJanuaryOnlyAfterDecember17()throws Exception{
  JSONObject selected=catalog(),regions=selected.getJSONObject("regions");int count=0;for(String region:keys(regions)){if(Set.of("동북아시아","대한민국").contains(region))continue;JSONArray cities=regions.getJSONArray(region);for(int i=0;i<cities.length();i++)for(boolean reverse:new boolean[]{false,true}){
   String code=cities.getJSONObject(i).getString("code"),a=reverse?code:"ICN",b=reverse?"ICN":code;JSONObject jan=month(a,b,"2027-01",true),dec=month(a,b,"2026-12",true);ReferenceMarkerRules.Context context=new ReferenceMarkerRules.Context();context.add(jan,1);JSONObject view=RepeatMarkerPolicy.calendar(dec,selected,context);for(int n=0;n<31;n++){JSONObject day=view.getJSONArray("dates").getJSONObject(n);assertEquals(code+" "+day.getString("date"),n>=17,RepeatMarkerPolicy.excluded(day));}assertEquals(14,view.getJSONObject("repeatMarkerPolicy").getJSONArray("excludedDates").length());assertNotNull(ReferenceMarkerRules.evaluate(dec,selected,context));count++;
   dec.put("carrier","OZ");assertNull(ReferenceMarkerRules.evaluate(dec,selected,context));
  }}assertTrue(count>=120);System.out.println("ALL_ROUTE_SCOPE_PASS: "+count+" directions; December boundary and OZ isolation");
 }
 JSONObject month(String a,String b,String month,boolean marked)throws Exception{JSONObject r=new JSONObject().put("carrier","KE").put("collectionMethod","MONTHLY_CALENDAR").put("origin",a).put("destination",b).put("month",month);JSONArray days=new JSONArray();YearMonth ym=YearMonth.parse(month);for(int n=1;n<=ym.lengthOfMonth();n++){JSONObject d=new JSONObject().put("date",ym.atDay(n).toString()).put("status","OBSERVED");for(String key:Search.ALL_FIELDS)d.put(key,marked);days.put(d);}return r.put("dates",days);}
 @Test public void partialMonthNeverBorrowsAcrossDirectionsOrOverridesKnownConflict()throws Exception{
  JSONObject selected=catalog(),prior=month("ICN","MXP","2027-09",true),current=month("ICN","MXP","2027-10",true);current.getJSONArray("dates").getJSONObject(30).put("status","UNKNOWN");ReferenceMarkerRules.Context context=new ReferenceMarkerRules.Context();context.add(prior,1);JSONObject view=RepeatMarkerPolicy.calendar(current,selected,context);assertEquals(30,view.getJSONObject("repeatMarkerPolicy").getJSONArray("excludedDates").length());assertFalse(RepeatMarkerPolicy.excluded(view.getJSONArray("dates").getJSONObject(30)));current.getJSONArray("dates").getJSONObject(2).put("prestigeAward",false);view=RepeatMarkerPolicy.calendar(current,selected,context);assertTrue(RepeatMarkerPolicy.review(view.getJSONArray("dates").getJSONObject(9)));assertFalse(RepeatMarkerPolicy.excluded(view.getJSONArray("dates").getJSONObject(9)));current.put("origin","MXP").put("destination","ICN");assertFalse(ReferenceMarkerRules.evaluate(current,selected,context).has("referenceMonth"));
 }
 @Test public void mixedFollowingMonthContinuesToOriginalMonthAfterItWithoutChangingMarks()throws Exception{
  JSONObject selected=catalog(),jan=month("ICN","ORD","2027-01",false),feb=month("ICN","ORD","2027-02",false),mar=month("ICN","ORD","2027-03",false);
  for(JSONObject r:new JSONObject[]{jan,feb}){JSONObject d=r.getJSONArray("dates").getJSONObject(r==jan?2:6);d.put("economyAward",true).put("prestigeAward",true).put("prestigeUpgrade",true);}
  ReferenceMarkerRules.Context context=new ReferenceMarkerRules.Context();context.add(feb,1);JSONObject before=RepeatMarkerPolicy.calendar(jan,selected,context);assertTrue(RepeatMarkerPolicy.review(before.getJSONArray("dates").getJSONObject(2)));
  context.add(mar,1);JSONObject view=RepeatMarkerPolicy.calendar(jan,selected,context),rule=view.getJSONObject("repeatMarkerPolicy");assertEquals(0,rule.getJSONArray("reviews").length());assertEquals(0,rule.getJSONArray("excludedDates").length());JSONObject decision=rule.getJSONArray("resolvedReviews").getJSONObject(0);assertEquals("2027-03",decision.getString("referenceMonth"));assertEquals("[\"2027-02\",\"2027-03\"]",decision.getJSONArray("referenceCheckedMonths").toString());assertTrue(SeatMarks.marked(view.getJSONArray("dates").getJSONObject(2),"prestigeAward",false));
 }

}
